// SupportNova API client.
//
// Every one of the backend's 84 operations, typed from the OpenAPI document
// (lib/api-types.d.ts, generated by `openapi-typescript`). If the backend
// changes shape, `next build` fails here rather than a page failing at runtime.
//
// Credentials: the access token lives in memory only. The refresh token never
// reaches this code -- it is an httpOnly cookie handled by the same-origin
// session proxy under app/api/session. There is no Supabase client, no
// service-role key and nothing in localStorage.

import type { components } from '@/lib/api-types'

export type S = components['schemas']

const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:8000'

/* ------------------------------------------------------------------ tokens */

let accessToken: string | null = null
export const setAccessToken = (t: string | null) => { accessToken = t }
export const getAccessToken = () => accessToken

/* ------------------------------------------------------------------ errors */

export class ApiError extends Error {
  constructor(public status: number, message: string, public detail?: unknown) {
    super(message)
    this.name = 'ApiError'
  }
}

/**
 * A readable sentence out of any error body this backend produces.
 *
 * It does not use FastAPI's default `{detail: ...}`. Every handled error
 * comes back as `{error: {code, message, details, request_id}}`, and a parser
 * that only knew `detail` silently replaced the server's actual explanation
 * with a generic fallback — which defeats the whole point of the API
 * bothering to explain itself.
 */
function describe(status: number, body: unknown): string {
  if (body && typeof body === 'object' && 'error' in body) {
    const e = (body as { error: unknown }).error
    if (e && typeof e === 'object') {
      const err = e as { message?: unknown; details?: { fields?: Array<{ field?: string; message?: string }> } }
      const fields = err.details?.fields
      if (Array.isArray(fields) && fields.length) {
        return fields.map((f) => (f.field ? `${f.field}: ${f.message}` : f.message)).join('; ')
      }
      if (typeof err.message === 'string' && err.message) return err.message
    }
  }
  if (body && typeof body === 'object' && 'detail' in body) {
    const d = (body as { detail: unknown }).detail
    if (typeof d === 'string') return d
    if (Array.isArray(d)) {
      return d
        .map((e) => {
          const loc = Array.isArray(e?.loc) ? e.loc.filter((x: unknown) => x !== 'body').join('.') : ''
          return loc ? `${loc}: ${e?.msg ?? 'invalid'}` : String(e?.msg ?? 'invalid')
        })
        .join('; ')
    }
    if (d && typeof d === 'object' && 'message' in d) return String((d as { message: unknown }).message)
  }
  if (status === 401) return 'Your session has expired. Please sign in again.'
  if (status === 403) return 'Your role does not allow that.'
  if (status === 404) return 'Not found.'
  if (status === 429) return 'Too many requests. Please wait a moment.'
  if (status >= 500) return 'The server had a problem. Please try again.'
  return `Request failed (${status}).`
}

/* ------------------------------------------------------------------ fetch */

type Opts = Omit<RequestInit, 'body'> & { body?: unknown; retried?: boolean; raw?: boolean }

let refreshing: Promise<boolean> | null = null
let sessionUser: User | null = null
export const getSessionUser = () => sessionUser

/** Rotate the session through the proxy. Concurrent callers share one attempt. */
export async function refreshSession(): Promise<boolean> {
  if (!refreshing) {
    refreshing = (async () => {
      try {
        const res = await fetch('/api/session/refresh', { method: 'POST', credentials: 'same-origin' })
        if (!res.ok) return false
        const data = (await res.json()) as SessionResponse
        accessToken = data.access_token
        sessionUser = data.user
        return true
      } catch {
        return false
      } finally {
        refreshing = null
      }
    })()
  }
  return refreshing
}

export async function apiFetch<T>(path: string, opts: Opts = {}): Promise<T> {
  const { body, retried, raw, headers: extraHeaders, ...init } = opts
  const isForm = typeof FormData !== 'undefined' && body instanceof FormData
  const headers: Record<string, string> = { ...(extraHeaders as Record<string, string>) }
  if (!isForm && body !== undefined) headers['Content-Type'] = 'application/json'
  if (accessToken) headers.Authorization = `Bearer ${accessToken}`

  let res: Response
  try {
    res = await fetch(`${API_BASE}${path}`, {
      ...init,
      headers,
      body: isForm ? (body as FormData) : body !== undefined ? JSON.stringify(body) : undefined,
    })
  } catch {
    throw new ApiError(0, 'The server could not be reached. Is the backend running?')
  }

  if (res.status === 401 && !retried) {
    if (await refreshSession()) return apiFetch<T>(path, { ...opts, retried: true })
    accessToken = null
    sessionUser = null
    if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent('auth:expired'))
  }

  if (!res.ok) {
    let parsed: unknown = null
    try { parsed = await res.json() } catch {}
    throw new ApiError(res.status, describe(res.status, parsed), parsed)
  }

  if (raw) return res as unknown as T
  if (res.status === 204) return undefined as T
  const text = await res.text()
  return (text ? JSON.parse(text) : undefined) as T
}

/** Build a query string, dropping empty values. */
export function qs(params?: object): string {
  if (!params) return ''
  const p = new URLSearchParams()
  for (const [k, v] of Object.entries(params as Record<string, unknown>)) {
    if (v === undefined || v === null || v === '') continue
    p.set(k, String(v))
  }
  const s = p.toString()
  return s ? `?${s}` : ''
}

function enc(s: string) { return encodeURIComponent(s) }

export const errorMessage = (e: unknown): string =>
  e instanceof ApiError ? e.message : e instanceof Error ? e.message : 'Something went wrong.'

/**
 * Multipart upload with real progress.
 *
 * `fetch` cannot report upload progress, and a 10 MB photo on a phone
 * connection with no feedback reads as a frozen page. XMLHttpRequest can.
 * Same auth rules as apiFetch: bearer header only, one silent refresh on 401.
 */
export function uploadWithProgress<T>(
  path: string,
  file: File,
  onProgress?: (fraction: number) => void,
  field = 'file',
  retried = false,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const xhr = new XMLHttpRequest()
    xhr.open('POST', `${API_BASE}${path}`)
    if (accessToken) xhr.setRequestHeader('Authorization', `Bearer ${accessToken}`)
    xhr.upload.onprogress = (e) => { if (e.lengthComputable) onProgress?.(e.loaded / e.total) }
    xhr.onerror = () => reject(new ApiError(0, 'The upload could not reach the server.'))
    xhr.onload = async () => {
      let parsed: unknown = null
      try { parsed = xhr.responseText ? JSON.parse(xhr.responseText) : null } catch {}
      if (xhr.status === 401 && !retried) {
        if (await refreshSession()) {
          try { resolve(await uploadWithProgress<T>(path, file, onProgress, field, true)) } catch (e) { reject(e) }
          return
        }
      }
      if (xhr.status >= 400) { reject(new ApiError(xhr.status, describe(xhr.status, parsed), parsed)); return }
      onProgress?.(1)
      resolve(parsed as T)
    }
    const form = new FormData()
    form.append(field, file)
    xhr.send(form)
  })
}

/* ------------------------------------------------------------------ live intake */

/** One step of a complaint's analysis, as the backend reports it. */
export interface ProgressStep {
  step: string
  state: 'active' | 'done' | 'skipped'
  label: string
  detail: string | null
  elapsed_ms: number
}

/**
 * Submit a complaint and follow its analysis step by step.
 *
 * The backend streams server-sent events: `step` as each stage starts and
 * finishes, then one `result` or `error`. EventSource cannot POST or send a
 * bearer header, so the stream is read from `fetch` directly.
 */
export async function submitWithProgress(
  data: S['ComplaintCreate'],
  analyse: boolean,
  onStep: (step: ProgressStep) => void,
  retried = false,
): Promise<S['IntakeResponse']> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json', Accept: 'text/event-stream' }
  if (accessToken) headers.Authorization = `Bearer ${accessToken}`

  let res: Response
  try {
    res = await fetch(`${API_BASE}/api/complaints/stream${qs({ analyse })}`, {
      method: 'POST', headers, body: JSON.stringify(data),
    })
  } catch {
    throw new ApiError(0, 'The server could not be reached. Is the backend running?')
  }
  if (res.status === 401 && !retried) {
    if (await refreshSession()) return submitWithProgress(data, analyse, onStep, true)
    accessToken = null
    sessionUser = null
    if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent('auth:expired'))
  }
  if (!res.ok || !res.body) {
    let parsed: unknown = null
    try { parsed = await res.json() } catch {}
    throw new ApiError(res.status, describe(res.status, parsed), parsed)
  }

  const reader = res.body.pipeThrough(new TextDecoderStream()).getReader()
  let buffer = ''
  let savedRef: string | null = null
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    buffer += value
    let cut: number
    while ((cut = buffer.indexOf('\n\n')) >= 0) {
      const block = buffer.slice(0, cut)
      buffer = buffer.slice(cut + 2)
      let kind = ''
      let payload = ''
      for (const line of block.split('\n')) {
        if (line.startsWith('event: ')) kind = line.slice(7)
        else if (line.startsWith('data: ')) payload += line.slice(6)
      }
      if (!kind || !payload) continue // a keep-alive comment
      const parsed = JSON.parse(payload)
      if (kind === 'step') {
        const step = parsed as ProgressStep
        if (step.step === 'saved' && step.state === 'done' && step.detail) savedRef = step.detail
        onStep(step)
      } else if (kind === 'result') {
        return parsed as S['IntakeResponse']
      } else if (kind === 'error') {
        const status = parsed?.error?.code === 'VALIDATION_ERROR' ? 422 : 500
        throw new ApiError(status, describe(status, parsed), parsed)
      }
    }
  }
  // The connection closed early. If the complaint was already saved it is not lost.
  throw new ApiError(
    0,
    savedRef
      ? `The connection dropped, but your complaint was saved as ${savedRef}. You can follow it from My complaints.`
      : 'The connection dropped before your complaint was saved. Please try again.',
  )
}

/* ------------------------------------------------------------------ shared types */

export type Role = 'customer' | 'agent' | 'reviewer' | 'manager' | 'admin' | 'evaluator'
export type User = Omit<S['UserOut'], 'role'> & { role: Role }
export interface SessionResponse { access_token: string; expires_in: number; user: User }
/** A correct password on an account with two-step sign-in: the code is still to come. */
export interface MfaChallenge { mfa_required: true; mfa_token: string }

export interface Page<T> { items: T[]; total: number; page?: number; page_size?: number }

export const COMPLAINT_STATUSES = [
  'NEW', 'ANALYZING', 'ANALYZED', 'VALIDATED', 'ASSIGNED', 'IN_PROGRESS', 'AWAITING_CUSTOMER',
  'ESCALATED', 'MANUAL_REVIEW', 'RESOLVED', 'CLOSED', 'REOPENED', 'FAILED',
] as const
export type ComplaintStatus = (typeof COMPLAINT_STATUSES)[number]

export const REVIEW_ACTIONS = [
  'APPROVE', 'REJECT', 'MODIFY', 'RECLASSIFY', 'REASSIGN', 'ESCALATE', 'REGENERATE', 'COMMENT', 'OVERRIDE',
] as const
export type ReviewAction = (typeof REVIEW_ACTIONS)[number]

export const URGENCIES = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'] as const
export const PRIORITIES = ['P0', 'P1', 'P2', 'P3'] as const
export const VERIFICATION_OUTCOMES = [
  'VERIFIED', 'VERIFIED_WITH_WARNING', 'CORRECTED_BY_RULES', 'MANUAL_REVIEW_REQUIRED', 'BLOCKED', 'INCOMPLETE',
] as const

/* Loosely-typed analytics dictionaries the backend returns as plain objects. */
export type VolumeSeries = S['VolumeOut'] & { series?: Array<{ date: string; count: number }> }
export interface MyQueue {
  assigned: number
  by_priority: Record<string, number>
  complaints: Array<{ public_ref: string; title: string; status: string; priority?: string | null; urgency?: string | null; escalation?: string | null }>
}

/* ------------------------------------------------------------------ auth */

export const auth = {
  /** Via the session proxy so the refresh token becomes an httpOnly cookie. */
  login: async (email: string, password: string): Promise<SessionResponse | MfaChallenge> => {
    const res = await fetch('/api/session/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
      credentials: 'same-origin',
    })
    if (!res.ok) {
      let parsed: unknown = null
      try { parsed = await res.json() } catch {}
      throw new ApiError(res.status, describe(res.status, parsed), parsed)
    }
    const data = (await res.json()) as SessionResponse | MfaChallenge
    if ('mfa_required' in data && data.mfa_required) return data
    const session = data as SessionResponse
    accessToken = session.access_token
    sessionUser = session.user
    return session
  },
  /** Second step of a two-step sign-in: an authenticator code or a recovery code. */
  loginMfa: async (mfa_token: string, code: string): Promise<SessionResponse> => {
    const res = await fetch('/api/session/login/mfa', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mfa_token, code }),
      credentials: 'same-origin',
    })
    if (!res.ok) {
      let parsed: unknown = null
      try { parsed = await res.json() } catch {}
      throw new ApiError(res.status, describe(res.status, parsed), parsed)
    }
    const data = (await res.json()) as SessionResponse
    accessToken = data.access_token
    sessionUser = data.user
    return data
  },
  /** Same proxy path as login, so the refresh token lands in the cookie. */
  register: async (email: string, full_name: string, password: string): Promise<SessionResponse> => {
    const res = await fetch('/api/session/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, full_name, password }),
      credentials: 'same-origin',
    })
    if (!res.ok) {
      let parsed: unknown = null
      try { parsed = await res.json() } catch {}
      throw new ApiError(res.status, describe(res.status, parsed), parsed)
    }
    const data = (await res.json()) as SessionResponse
    accessToken = data.access_token
    sessionUser = data.user
    return data
  },
  refresh: refreshSession,
  me: () => apiFetch<User>('/api/auth/me'),
  changePassword: (current_password: string, new_password: string) =>
    apiFetch<S['MessageResponse']>('/api/auth/change-password', { method: 'POST', body: { current_password, new_password } }),
  updateMe: (full_name: string) => apiFetch<User>('/api/auth/me', { method: 'PATCH', body: { full_name } }),
  security: () => apiFetch<S['SecurityOverview']>('/api/auth/security'),
  sessions: () => apiFetch<S['SessionOut'][]>('/api/auth/sessions'),
  revokeSession: (id: string) => apiFetch<S['MessageResponse']>(`/api/auth/sessions/${enc(id)}`, { method: 'DELETE' }),
  revokeOtherSessions: () => apiFetch<S['MessageResponse']>('/api/auth/sessions/revoke-others', { method: 'POST' }),
  activity: (limit = 30) => apiFetch<S['ActivityOut'][]>(`/api/auth/activity${qs({ limit })}`),
  mfaSetup: () => apiFetch<S['MfaSetupOut']>('/api/auth/mfa/setup', { method: 'POST' }),
  mfaEnable: (code: string) => apiFetch<S['RecoveryCodesOut']>('/api/auth/mfa/enable', { method: 'POST', body: { code } }),
  mfaDisable: (password: string, code: string) => apiFetch<S['MessageResponse']>('/api/auth/mfa/disable', { method: 'POST', body: { password, code } }),
  mfaRecoveryCodes: (code: string) => apiFetch<S['RecoveryCodesOut']>('/api/auth/mfa/recovery-codes', { method: 'POST', body: { code } }),
  logout: async () => {
    try {
      await fetch('/api/session/logout', {
        method: 'POST',
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : {},
        credentials: 'same-origin',
      })
    } finally {
      accessToken = null
      sessionUser = null
    }
  },
}

