/* ------------------------------------------------------------------ complaints */

export interface ComplaintFilters {
  page?: number; size?: number; status?: string; category?: string; department?: string
  urgency?: string; priority?: string; verification_outcome?: string; requires_review?: boolean
  dataset_tag?: string; customer_type?: string; sentiment?: string; escalation?: string
  date_from?: string; date_to?: string; search?: string
}

export interface ResponseDraft {
  version: number; tone?: string; draft_text?: string | null; final_text?: string | null
  guard_status?: string; citations?: unknown[]; flags?: unknown[]; approved_at?: string | null; sent_at?: string | null
}
export interface AgentItem {
  public_ref: string; title: string; status: string; assigned_to_me: boolean
  category: string | null; priority: string | null; urgency: string | null; sentiment: string | null
  team: string | null; summary: string | null
  recommendation: { primary_issue?: string | null; steps: string[]; escalation_reason?: string | null } | null
  validation: { outcome: string | null; agreement_pct: number | null; requires_review: boolean }
  suggested_response: { text: string | null; guard_status: string; version: number } | null
  escalation_warnings: string[]; due_at: string | null
}
export interface AgentWorkspace {
  scope: 'mine' | 'all'; team: string | null
  counts: { total: number; assigned_to_me: number; with_warnings: number; needs_review: number; without_reply: number }
  complaints: AgentItem[]
}

export const complaints = {
  list: (f?: ComplaintFilters) => apiFetch<Page<S['ComplaintSummary']>>(`/api/complaints${qs(f)}`),
  mine: (page = 1, size = 20) => apiFetch<Page<S['ComplaintStatusOut']>>(`/api/complaints/mine${qs({ page, size })}`),
  create: (data: S['ComplaintCreate'], analyse = true) =>
    apiFetch<S['IntakeResponse']>(`/api/complaints${qs({ analyse })}`, { method: 'POST', body: data }),
  get: (ref: string) => apiFetch<S['ComplaintDetail']>(`/api/complaints/${enc(ref)}`),
  explain: (ref: string) => apiFetch<S['ExplainResponse']>(`/api/complaints/${enc(ref)}/explain`),
  reanalyse: (ref: string, run_genai = true) =>
    apiFetch<S['ReanalyseResponse']>(`/api/complaints/${enc(ref)}/reanalyse${qs({ run_genai })}`, { method: 'POST' }),
  status: (ref: string) => apiFetch<S['ComplaintStatusOut']>(`/api/complaints/${enc(ref)}/status`),
  changeStatus: (ref: string, to_status: string, reason?: string) =>
    apiFetch<S['LifecycleOut']>(`/api/complaints/${enc(ref)}/status`, { method: 'POST', body: { to_status, reason } }),
  checklist: (ref: string) => apiFetch<S['ChecklistOut']>(`/api/complaints/${enc(ref)}/checklist`),
  confirmStep: (ref: string, stepId: string) =>
    apiFetch<S['ChecklistOut']>(`/api/complaints/${enc(ref)}/checklist/${enc(stepId)}/confirm`, { method: 'POST' }),
  followUps: (ref: string) => apiFetch<S['FollowUpOut'][]>(`/api/complaints/${enc(ref)}/follow-ups`),
  completeFollowUp: (ref: string, id: string) =>
    apiFetch<S['FollowUpOut'][]>(`/api/complaints/${enc(ref)}/follow-ups/${enc(id)}/complete`, { method: 'POST' }),
  escalation: (ref: string) => apiFetch<S['schemas__complaints__EscalationOut']>(`/api/complaints/${enc(ref)}/escalation`),
  lifecycle: (ref: string) => apiFetch<S['LifecycleOut']>(`/api/complaints/${enc(ref)}/lifecycle`),
  responses: (ref: string) => apiFetch<ResponseDraft[]>(`/api/complaints/${enc(ref)}/responses`),
  draftResponse: (ref: string) => apiFetch<ResponseDraft>(`/api/complaints/${enc(ref)}/responses`, { method: 'POST' }),

  /* ── what the customer can do after submitting ── */
  answer: (ref: string, questionId: string, answer: string) =>
    apiFetch<S['ClarificationAnswerOut']>(
      `/api/complaints/${enc(ref)}/clarifications/${enc(questionId)}/answer`,
      { method: 'POST', body: { answer } },
    ),
  /** Nothing is stored and no model is called; safe to run on every pause in typing. */
  preview: (title: string, description: string) =>
    apiFetch<S['PreviewOut']>('/api/complaints/preview', { method: 'POST', body: { title, description } }),
  uploadEvidence: (ref: string, file: File, onProgress?: (fraction: number) => void) =>
    uploadWithProgress<S['EvidenceOut']>(`/api/complaints/${enc(ref)}/evidence`, file, onProgress),
  /** Fetched with the bearer header and saved as a blob; the token never goes in a URL. */
  downloadEvidence: async (ref: string, evidenceId: string, fileName: string) => {
    const res = await apiFetch<Response>(`/api/complaints/${enc(ref)}/evidence/${enc(evidenceId)}`, { raw: true })
    const url = URL.createObjectURL(await res.blob())
    const a = document.createElement('a')
    a.href = url
    a.download = fileName
    a.click()
    URL.revokeObjectURL(url)
  },
}

